import{_ as i,o as t,c as l,a0 as a}from"./chunks/framework.DQOulFGV.js";const e="data:image/svg+xml;base64,",g="data:image/svg+xml;base64,",d="data:image/svg+xml;base64,",C=JSON.parse('{"title":"第3章 缓存雪崩","description":"","frontmatter":{},"headers":[],"relativePath":"redis/03-cache-engineering/chapter-03-avalanche.md","filePath":"redis/03-cache-engineering/chapter-03-avalanche.md"}'),Z={name:"redis/03-cache-engineering/chapter-03-avalanche.md"};function m(s,I,M,h,y,j){return t(),l("div",null,[...I[0]||(I[0]=[a('<h1 id="第3章-缓存雪崩" tabindex="-1">第3章 缓存雪崩 <a class="header-anchor" href="#第3章-缓存雪崩" aria-label="Permalink to &quot;第3章 缓存雪崩&quot;">​</a></h1><blockquote><p>缓存雪崩指「大量缓存 key 同时失效」或「缓存服务整体宕机」，导致海量请求瞬间直达数据库，把数据库打垮。本章讲解雪崩的成因与多种缓解手段。</p></blockquote><hr><h2 id="_3-1-问题" tabindex="-1">3.1 问题 <a class="header-anchor" href="#_3-1-问题" aria-label="Permalink to &quot;3.1 问题&quot;">​</a></h2><p>雪崩有两种成因：</p><table tabindex="0"><thead><tr><th style="text-align:left;">成因</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">大量 key 同时过期</td><td style="text-align:left;">同一时间设置了相同 TTL 的 key 集体失效</td></tr><tr><td style="text-align:left;">缓存服务宕机</td><td style="text-align:left;">Redis 整体不可用，所有请求直达数据库</td></tr></tbody></table><p><img src="'+e+`" alt="缓存雪崩成因"></p><p>危害：数据库瞬时并发激增，连接耗尽，整个系统不可用。</p><hr><h2 id="_3-2-ttl-随机化" tabindex="-1">3.2 TTL 随机化 <a class="header-anchor" href="#_3-2-ttl-随机化" aria-label="Permalink to &quot;3.2 TTL 随机化&quot;">​</a></h2><p>给每个 key 的过期时间加上随机偏移，让它们错峰过期，避免「同时过期」。</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 伪代码：设置 5 分钟过期 + 0~60 秒随机偏移</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ttl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 300</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Random</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">().</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nextInt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">60</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">redis.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(key, value, ttl);</span></span></code></pre></div><p>要点：</p><table tabindex="0"><thead><tr><th style="text-align:left;">要点</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">固定基础值</td><td style="text-align:left;">保持一个基准 TTL（如 300 秒）</td></tr><tr><td style="text-align:left;">随机偏移</td><td style="text-align:left;">叠加一个随机范围（如 0~60 秒）</td></tr><tr><td style="text-align:left;">错峰失效</td><td style="text-align:left;">不同 key 过期时间分散，避免同点洪峰</td></tr></tbody></table><hr><h2 id="_3-3-多级缓存" tabindex="-1">3.3 多级缓存 <a class="header-anchor" href="#_3-3-多级缓存" aria-label="Permalink to &quot;3.3 多级缓存&quot;">​</a></h2><p>在 Redis 之上再加一层「本地缓存」（如 Caffeine、Guava Cache），形成多级缓存：</p><p><img src="`+g+'" alt="多级缓存流程"></p><table tabindex="0"><thead><tr><th style="text-align:left;">层级</th><th style="text-align:left;">说明</th><th style="text-align:left;">特点</th></tr></thead><tbody><tr><td style="text-align:left;">L1 本地缓存</td><td style="text-align:left;">进程内，最快</td><td style="text-align:left;">各实例独立，容量小</td></tr><tr><td style="text-align:left;">L2 Redis</td><td style="text-align:left;">分布式缓存</td><td style="text-align:left;">共享，容量大</td></tr><tr><td style="text-align:left;">DB</td><td style="text-align:left;">最终数据源</td><td style="text-align:left;">最慢</td></tr></tbody></table><p>即使 Redis 宕机，本地缓存仍能兜住一部分热点请求，减少直达数据库的压力。</p><hr><h2 id="_3-4-熔断与降级" tabindex="-1">3.4 熔断与降级 <a class="header-anchor" href="#_3-4-熔断与降级" aria-label="Permalink to &quot;3.4 熔断与降级&quot;">​</a></h2><p>当检测到缓存不可用、数据库压力过大时，主动熔断降级，保护数据库。</p><table tabindex="0"><thead><tr><th style="text-align:left;">手段</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">熔断</td><td style="text-align:left;">缓存服务异常时，快速失败，不再穿透</td></tr><tr><td style="text-align:left;">降级</td><td style="text-align:left;">返回兜底数据（默认值、静态页）而非查库</td></tr><tr><td style="text-align:left;">限流</td><td style="text-align:left;">限制打到数据库的请求速率</td></tr></tbody></table><p><img src="'+d+'" alt="熔断降级流程"></p><hr><h2 id="_3-5-三大问题对比" tabindex="-1">3.5 三大问题对比 <a class="header-anchor" href="#_3-5-三大问题对比" aria-label="Permalink to &quot;3.5 三大问题对比&quot;">​</a></h2><p>缓存穿透、击穿、雪崩常被一起考察，核心区别在于「失效范围」：</p><table tabindex="0"><thead><tr><th style="text-align:left;">问题</th><th style="text-align:left;">失效对象</th><th style="text-align:left;">数据是否存在</th><th style="text-align:left;">触发特征</th></tr></thead><tbody><tr><td style="text-align:left;">穿透</td><td style="text-align:left;">不存在的 key</td><td style="text-align:left;">数据库也不存在</td><td style="text-align:left;">单点重复，恶意查询</td></tr><tr><td style="text-align:left;">击穿</td><td style="text-align:left;">单个热点 key</td><td style="text-align:left;">数据库存在</td><td style="text-align:left;">单点瞬间过期</td></tr><tr><td style="text-align:left;">雪崩</td><td style="text-align:left;">大量 key 或整个服务</td><td style="text-align:left;">数据库存在</td><td style="text-align:left;">大面积同时失效</td></tr></tbody></table><p>判别口诀：<strong>穿透查不到（数据本身没有）、击穿点过期（单个热点）、雪崩面过期（大面积/服务宕机）</strong>。</p>',30)])])}const c=i(Z,[["render",m]]);export{C as __pageData,c as default};
